const unpackedCache = new Map();

export function hasRealMidiScore(pieceId) {
  return Object.prototype.hasOwnProperty.call(PACKED_CLASSICAL_MIDI, pieceId);
}

export function getRealMidiMeta(pieceId) {
  const entry = PACKED_CLASSICAL_MIDI[pieceId];
  if (!entry) return null;
  return {
    durationSec: entry.d,
    bpm: entry.b,
    noteCount: entry.n.length >> 2,
  };
}

export function unpackRealMidiScore(pieceId) {
  if (unpackedCache.has(pieceId)) return unpackedCache.get(pieceId);
  const entry = PACKED_CLASSICAL_MIDI[pieceId];
  if (!entry) return null;

  const arr = entry.n;
  const bpm = entry.b || 84;
  const beatsPerSec = bpm / 60.0;
  const count = arr.length >> 2;
  const alignedNotes = new Array(count);
  let tMs = 0;
  for (let i = 0; i < count; i++) {
    const o = i * 4;
    tMs += arr[o];
    const t = tMs * 0.001;
    const dur = arr[o + 1] * 0.001;
    const mh = arr[o + 2];
    const midi = mh >> 1;
    const hand = (mh & 1) === 1 ? "RH" : "LH";
    const vel = arr[o + 3] * 0.01;
    alignedNotes[i] = [
      t,
      dur,
      Math.max(0, (t - 0.28) * beatsPerSec),
      Math.max(0.12, dur * beatsPerSec),
      midi,
      vel,
      hand,
    ];
  }

  const pArr = entry.p || [];
  const pCount = pArr.length >> 1;
  const kneePedal = new Array(pCount);
  for (let i = 0; i < pCount; i++) {
    kneePedal[i] = [pArr[i * 2] * 0.01, pArr[i * 2 + 1] * 0.01];
  }

  const result = {
    durationSec: entry.d,
    bpm,
    alignedNotes,
    kneePedal,
  };
  unpackedCache.set(pieceId, result);
  return result;
}
